import {
  Frontmatter,
  CONCEPT_NAME,
  BUNDLE,
  splitFrontmatter,
  parseFrontmatter,
} from "./helpers/schema.ts";
import {
  timelineProblems,
  evidenceProblems,
  undefinedCodes,
  bundleEntryProblem,
  supersessionProblems,
  layoutFindings,
} from "./helpers/check.ts";

// The object follows dx's TypeDefinition contract; dx validates it when loading the revision.
export default {
  name: "retro",
  match: "records/*.md",
  format: "markdown-frontmatter",
  id: (file: { name: string }) => file.name,
  filename: CONCEPT_NAME,
  schema: Frontmatter,
  links: { superseded_by: { to: "retro" } },
  immutable: false,
  review: { rubric: "rubrics/retro-review-v4.toml", place: "file:.dx/verdicts/*.jsonl" },
  checks: [
    async (
      record: { id: string; path: string },
      tree: { files: Readonly<Record<string, string>>; records: readonly { id: string }[] },
    ) => {
      const text = tree.files[record.path] ?? "";
      const problems: string[] = [];
      const name = record.path.slice(`${BUNDLE}/`.length);
      const naming = bundleEntryProblem(name, false);
      if (naming !== null) problems.push(naming);
      // Preserve the old gate's exact LF-only frontmatter acceptance, even though dx's
      // adapter also accepts BOM/CRLF and a closing delimiter without a newline.
      const { yaml } = splitFrontmatter(text);
      if (yaml === null) problems.push("missing frontmatter");
      else {
        const fm = parseFrontmatter(yaml);
        if (fm.isOk())
          problems.push(
            ...supersessionProblems(fm.value, new Set(tree.records.map((row) => row.id))),
          );
        else problems.push(fm.error);
      }
      problems.push(
        ...timelineProblems(text),
        ...(await evidenceProblems(text, record.path, (path) => tree.files[path] !== undefined)),
      );
      for (const { code, line } of undefinedCodes(text))
        problems.push(`terms: undefined code ${code} at line ${line}`);
      const layout =
        tree.records[0]?.id === record.id ? layoutFindings(Object.keys(tree.files)) : [];
      return [
        ...problems.map((problem) => ({
          check: "retro.deterministic",
          id: record.id,
          path: record.path,
          field: problem,
          message: problem,
        })),
        ...layout.map((row) => ({
          check: "retro.layout",
          path: row.path,
          field: row.problem,
          message: row.problem,
        })),
      ];
    },
  ],
};

