// Pure record policy shared by dx and the legacy adapters.
import { err, fromThrowable, ok } from "neverthrow";
import { z } from "zod";
export const BUNDLE = "records";
const message = (e: unknown): string => (e instanceof Error ? e.message : String(e));
export const parseYaml = fromThrowable((text: string): unknown => Bun.YAML.parse(text), message);
export const parseToml = fromThrowable((text: string): unknown => Bun.TOML.parse(text), message);
export function parseFrontmatter(yaml: string) {
  return parseYaml(yaml).andThen((value) => {
    const parsed = Frontmatter.safeParse(value);
    return parsed.success
      ? ok(parsed.data)
      : err(z.prettifyError(parsed.error).replaceAll("\n", "; "));
  });
}
export const RAW = "raw";
export const INDEX = "index.md";
// Bundle .md files that are not concepts (OKF §3.1).
export const RESERVED = new Set([INDEX, "log.md"]);

// Shared technical vocabulary for this repository's record writers and readers.
export const COMMON_CODES = new Set([
  // Git vocabulary names objects and the standard project readme.
  "HEAD",
  "README",
  // POSIX environment variables are conventional names readers can identify directly.
  "HOME",
  "LANG",
  "LC_ALL",
  "LOGNAME",
  "MAIL",
  "NLSPATH",
  "PATH",
  "PWD",
  "SHELL",
  "TMPDIR",
  "USER",
  // Standard errno names identify operating-system failures without project-specific expansion.
  "ENOSPC",
  // Common status and work-queue words are self-explanatory in technical records.
  "FAILED",
  "PASS",
  "FAIL",
  "TODO",
  "JST", // Japan Standard Time: house record time zone.
  "UTC", // Coordinated Universal Time: portable timestamps.
  "ISO", // International Organization for Standardization: date formats.
  "URL", // Uniform Resource Locator: links.
  "JSON", // JavaScript Object Notation: structured data.
  "TOML", // Tom's Obvious Minimal Language: repository configuration.
  "YAML", // YAML Ain't Markup Language: record frontmatter.
  "CLI", // Command-line interface: house tools.
  "API", // Application programming interface: tool integrations.
  "LLM", // Large language model: agent models.
  "CI", // Continuous integration: automated checks.
  "PR", // Pull request: change review.
  "ID", // Identifier: record keys.
  "HTTP", // Hypertext Transfer Protocol: network requests.
  "SHA", // Secure Hash Algorithm: content digests.
  "TS", // TypeScript: house scripting language.
  "MD", // Markdown: record format.
  "OK", // Conventional success acknowledgement.
  "CPU", // Central processing unit: fleet compute resources.
  "GPU", // Graphics processing unit: fleet compute resources.
  "RAM", // Random-access memory: fleet memory capacity.
  "OS", // Operating system: fleet hosts.
  "GB", // Gigabytes: storage and memory quantities in records.
  "MB", // Megabytes: storage and memory quantities in records.
]);
export const CODE_TOKEN = /\b[A-Z][A-Z0-9]*(?:[-_][A-Z0-9]+)+\b|\b[A-Z]{2,}[0-9]*\b/gu;

// {yyyymmdd}_{hyphen-connected-slug}: the date is the last day of the period the record covers (JST).
const SLUG = "[a-z0-9]+(?:-[a-z0-9]+)*";
export const CONCEPT_NAME = new RegExp(`^(\\d{4})(\\d{2})(\\d{2})_${SLUG}\\.md$`, "u");
export const RAW_NAME = new RegExp(`^(\\d{4})(\\d{2})(\\d{2})_${SLUG}\\.(?!md$)[a-z0-9]+$`, "u");

export const TYPES = [
  "Retrospective",
  "Postmortem",
  "Issue Structure Analysis",
  "Frustration Review",
  "Design Note",
  "Hearing",
] as const;

const conceptName = z.string().regex(CONCEPT_NAME, "expected {yyyymmdd}_{slug}.md");
// OKF §7 actor: human:<id>, process:<id>, or <producer>/<version>.
const actor = z
  .string()
  .regex(/^(?:(?:human|process):\S+|[^\s:/]+\/\S+)$/u, "expected an OKF actor");

export const Review = z.strictObject({
  rubric: z.string().min(1),
  by: actor,
  at: z.iso.datetime({ offset: true }),
  sha256: z.string().regex(/^[0-9a-f]{64}$/u),
  bits: z.number().int().min(0).max(3),
  p: z.array(z.number().min(0).max(1)).length(2),
});

// OKF v0.2 concept frontmatter. Only `type` is required by OKF; `title` is required here so the
// index needs no body parsing. Unknown keys are kept (OKF §4.1 extensions).
export const Frontmatter = z.looseObject({
  type: z.enum(TYPES),
  title: z.string().min(1),
  description: z.string().min(1).optional(),
  status: z.enum(["draft", "stable", "deprecated"]).optional(),
  tags: z
    .array(z.string().regex(new RegExp(`^${SLUG}$`, "u"), "expected a lowercase kebab tag"))
    .optional(),
  generated: z.object({ by: actor, at: z.iso.datetime({ offset: true }) }).optional(),
  superseded_by: conceptName.optional(),
  review: Review.optional(),
});
export type Frontmatter = z.infer<typeof Frontmatter>;

const plainDate = fromThrowable(
  (year: number, month: number, d: number) =>
    Temporal.PlainDate.from({ year, month, day: d }, { overflow: "reject" }),
  () => "invalid date",
);
export function validDay(y: string, m: string, d: string): boolean {
  return plainDate(Number(y), Number(m), Number(d)).isOk();
}

export function splitFrontmatter(text: string): { yaml: string | null; body: string } {
  if (!text.startsWith("---\n")) return { yaml: null, body: text };
  const end = text.indexOf("\n---\n", 4);
  if (end < 0) return { yaml: null, body: text };
  return { yaml: text.slice(4, end), body: text.slice(end + 5) };
}

// Shared offline review contract; importing this module never loads a judge client.
export const REVIEW_RUBRIC = "tools/review/retro-review-v4.toml";
const rubricSchema = z
  .object({
    rubric: z.string().min(1),
    criteria: z
      .array(
        z.object({
          bit: z.number().int().min(0).max(1),
          id: z.string().min(1),
          question: z.string().min(1),
        }),
      )
      .length(2),
  })
  .refine(
    (value) =>
      new Set(value.criteria.map((row) => row.bit)).size === 2 &&
      new Set(value.criteria.map((row) => row.id)).size === 2,
    "Two unique bits and ids required",
  );
export type Rubric = z.infer<typeof rubricSchema>;

export function parseRubric(text: string) {
  return fromThrowable(
    (input: string): unknown => Bun.TOML.parse(input),
    String,
  )(text).andThen((value) => {
    const parsed = rubricSchema.safeParse(value);
    return parsed.success
      ? ok({ ...parsed.data, criteria: parsed.data.criteria.toSorted((a, b) => a.bit - b.bit) })
      : err(parsed.error.message);
  });
}

// Keep source offsets: serializing the whole YAML document would change unrelated bytes.
export function splitRecord(text: string) {
  const match = /^(?:\uFEFF)?---\r?\n([\s\S]*?)^---(?:\r?\n|$)/mu.exec(text);
  if (match?.index !== 0 || match[1] === undefined)
    return { header: "", body: text, newline: "\n", present: false };
  const opening = match[0].indexOf("\n") + 1;
  return {
    header: match[1],
    body: text.slice(match[0].length),
    newline: match[0].includes("\r\n") ? "\r\n" : "\n",
    present: true,
    opening: text.slice(0, opening),
    closing: match[0].slice(opening + match[1].length),
  };
}

export function withoutReview(text: string) {
  const parts = splitRecord(text);
  if (!parts.present) return text;
  const lines = parts.header.match(/[^\n]*\n|[^\n]+$/gu) ?? [];
  const kept: string[] = [];
  let removing = false;
  let removed = false;
  for (const line of lines) {
    if (/^(?:review|"review"|'review')\s*:/u.test(line)) {
      removing = true;
      removed = true;
      continue;
    }
    if (removing && /^[ \t]+\S/u.test(line)) continue;
    if (removing && /^\s*$/u.test(line)) {
      kept.push(line);
      continue;
    }
    removing = false;
    kept.push(line);
  }
  const header = kept.join("");
  if (header === "") return parts.body;
  if (!removed) return text;
  return `${parts.opening ?? `---${parts.newline}`}${header}${parts.closing ?? `---${parts.newline}`}${parts.body}`;
}

policy..dx/helpers/check.ts:
import {
  BUNDLE,
  RAW,
  RESERVED,
  CONCEPT_NAME,
  RAW_NAME,
  COMMON_CODES,
  CODE_TOKEN,
  validDay,
  type Frontmatter,
} from "./schema.ts";
export type Finding = { path: string; problem: string };

const timeToken = /(?<![\d:+-])(\d{2}):(\d{1,2})([a-y])?\b/giu;
const zoneAfterTime =
  /^(?:\s*(?:JST|UTC|Z|[+-]\d{2}:\d{2})\b|:\d{2}(?:\.\d+)?\s*(?:JST|UTC|Z|[+-]\d{2}:\d{2})\b)/iu;
const markdownLink = /!?(?:\[[^\]]*\])\(\s*(?:<([^>]+)>|([^\s)]+))(?:\s+[^)]*)?\)/gu;
const referenceLink = /^\s*\[[^\]]+\]:\s*(?:<([^>]+)>|(\S+))/gmu;

function linkTargetEnd(line: string, start: number): number | undefined {
  let depth = 1;
  let end = start;
  for (; end < line.length && depth > 0; end += 1) {
    if (line[end] === "\\") end += 1;
    else if (line[end] === "(") depth += 1;
    else if (line[end] === ")") depth -= 1;
  }
  return depth === 0 ? end - 1 : undefined;
}

function maskLinkTargets(line: string): string {
  // Inline destinations may contain balanced parentheses, escaped bytes and optional titles.
  const chars = line.split("");
  for (const match of line.matchAll(/\]\(/gu)) {
    const end = linkTargetEnd(line, match.index + 2);
    if (end === undefined) continue;
    // UTF-16 offsets match RegExp.index even in Japanese records.
    chars.fill(" ", match.index + 2, end);
  }
  const masked = chars
    .join("")
    .replaceAll(/<(?:[a-z][a-z\d+.-]*:[^<>\s]*|[^<>\s@]+@[^<>\s@]+)>/giu, (target) =>
      " ".repeat(target.length),
    );
  return masked.replace(
    /^( {0,3}\[[^\]]+\]:\s*).+$/u,
    (_match, prefix: string) => prefix + " ".repeat(masked.length - prefix.length),
  );
}

function nextTermsLevel(
  line: string,
  current: number | undefined,
  nextLine = "",
): number | undefined {
  const heading = /^ {0,3}(#{1,6})\s+(.+?)\s*#*\s*$/u.exec(line);
  const underline = /^ {0,3}(=+|-+)\s*$/u.exec(nextLine);
  const setextLevel = underline?.[1]?.startsWith("=") === true ? 1 : 2;
  const level = heading?.[1]?.length ?? (underline === null ? undefined : setextLevel);
  if (level === undefined) return current;
  if (/^(?:Terms|用語)$/iu.test(heading?.[2] ?? line.trim())) return level;
  return current !== undefined && level <= current ? undefined : current;
}

// Mask excluded bytes rather than deleting them so first-use line numbers stay absolute.
function termsText(text: string): string {
  let fence: { marker: string; length: number } | undefined;
  const visible = text
    .split("\n")
    .map((line) => {
      const delimiter = /^ {0,3}(`{3,}|~{3,})(.*)$/u.exec(line);
      if (fence !== undefined) {
        if (
          delimiter?.[1]?.[0] === fence.marker &&
          delimiter[1].length >= fence.length &&
          delimiter[2]?.trim() === ""
        )
          fence = undefined;
        return " ".repeat(line.length);
      }
      if (delimiter?.[1] !== undefined) {
        fence = { marker: delimiter[1][0] ?? "`", length: delimiter[1].length };
        return " ".repeat(line.length);
      }
      return maskLinkTargets(line);
    })
    .join("\n");
  return visible;
}

function termPattern(code: string): RegExp {
  const escaped = code.replaceAll(/[.*+?^${}()|[\]\\]/gu, "\\$&");
  return new RegExp(`^${escaped.replaceAll(/(?<![A-Z])NN?(?![A-Z])/gu, "[0-9]+")}$`, "u");
}

const POSIX_ENVIRONMENT_VARIABLES = new Set([
  "HOME",
  "LANG",
  "LC_ALL",
  "LOGNAME",
  "MAIL",
  "NLSPATH",
  "PATH",
  "PWD",
  "SHELL",
  "TMPDIR",
  "USER",
]);

function isPathOrEnvironmentOccurrence(text: string, index: number, code: string): boolean {
  const lineStart = text.lastIndexOf("\n", index - 1) + 1;
  const lineEnd = text.indexOf("\n", index);
  const line = text.slice(lineStart, lineEnd < 0 ? undefined : lineEnd);
  const start = index - lineStart;
  const end = start + code.length;
  const before = line.slice(0, start);
  const after = line.slice(end);

  // File extensions and path separators make a token part of a name or path, not prose.
  if (/^\.[a-z][a-z0-9]*(?:\b|$)/u.test(after) || /^_[a-z][a-z0-9]*(?:\b|$)/u.test(after))
    return true;
  const paths = /(?:\.{1,2}\/|\/)?[A-Za-z0-9._-]+(?:\/[A-Za-z0-9._-]+)+/gu;
  if (
    [...line.matchAll(paths)].some(
      (match) => (match.index ?? 0) <= start && (match.index ?? 0) + match[0].length >= end,
    )
  )
    return true;

  // Shell-variable notation is self-identifying when the token is a valid shell name.
  if (before.endsWith("${") && after.startsWith("}") && /^[A-Z_][A-Z0-9_]*$/u.test(code))
    return true;
  if (before.endsWith("$") && /^[A-Z_][A-Z0-9_]*$/u.test(code)) return true;
  return POSIX_ENVIRONMENT_VARIABLES.has(code) && before.endsWith("`") && after.startsWith("`");
}

export function undefinedCodes(text: string): { code: string; line: number }[] {
  const visible = termsText(text);
  const definitions: RegExp[] = [];
  let termsLevel: number | undefined;
  const lines = visible.split("\n");
  for (const [index, line] of lines.entries()) {
    termsLevel = nextTermsLevel(line, termsLevel, lines[index + 1]);
    if (termsLevel === undefined) continue;
    const cell = /^\s*\|?\s*([^|]+)\|/u.exec(line)?.[1];
    if (cell === undefined) continue;
    for (const match of cell.matchAll(CODE_TOKEN)) {
      definitions.push(new RegExp(`^${match[0]}$`, "u"), termPattern(match[0]));
    }
  }
  const first = new Map<string, { index: number; line: number }>();
  let line = 1;
  let previous = 0;
  for (const match of visible.matchAll(CODE_TOKEN)) {
    line += (visible.slice(previous, match.index).match(/\n/gu) ?? []).length;
    previous = match.index;
    if (isPathOrEnvironmentOccurrence(visible, match.index, match[0])) continue;
    if (!first.has(match[0])) first.set(match[0], { index: match.index, line });
  }
  const undefinedTerms: { code: string; line: number }[] = [];
  for (const [code, use] of first) {
    if (COMMON_CODES.has(code) || definitions.some((pattern) => pattern.test(code))) continue;
    const before = visible.slice(visible.lastIndexOf("\n", use.index - 1) + 1, use.index);
    const after = visible.slice(use.index + code.length).split("\n", 1)[0] ?? "";
    // Inline formatting around a code does not change its first-use meaning.
    const expandedAfter = /^[`*_]*\s*[（(]\s*[^()（）\n]*[^\s()（）][^()（）\n]*[)）]/u.test(after);
    const expandedBefore =
      /[^\s([\]（|`*_][^()（）\n]*\s*[（(][`*_]*$/u.test(before) && /^[`*_]*[)）]/u.test(after);
    if (!expandedAfter && !expandedBefore) undefinedTerms.push({ code, line: use.line });
  }
  return undefinedTerms;
}

function dateExists(text: string): boolean {
  const dates = [...text.matchAll(/\b(\d{4})-(\d{2})-(\d{2})\b|\b(\d{4})(\d{2})(\d{2})\b/gu)];
  return dates.some((match) => {
    const year = match[1] ?? match[4] ?? "";
    const month = match[2] ?? match[5] ?? "";
    const day = match[3] ?? match[6] ?? "";
    return validDay(year, month, day);
  });
}

export function timelineProblems(text: string): string[] {
  const problems: string[] = [];
  if (!dateExists(text)) problems.push("timeline: record has no valid date");
  for (const match of text.matchAll(timeToken)) {
    const hour = Number(match[1]);
    const minute = Number(match[2]);
    const token = match[0];
    if (match[2]?.length !== 2 || match[3] !== undefined || hour > 23 || minute > 59) {
      problems.push(`timeline: invalid time ${token}`);
      continue;
    }
    const suffix = text.slice((match.index ?? 0) + token.length);
    if (!zoneAfterTime.test(suffix)) problems.push(`timeline: time ${token} has no time zone`);
  }
  return problems;
}

// Repo-relative POSIX paths are supplied by dx and by the legacy filesystem adapter.
export function resolveLink(
  target: string,
  recordPath: string,
): { path?: string; problem?: string } {
  if (/^(?:[a-z][a-z\d+.-]*:|#|\/)/iu.test(target)) return {};
  const linkPath = target.split(/[?#]/u, 1)[0] ?? "";
  if (linkPath === "") return {};
  const parts = recordPath.split("/").slice(0, -1);
  for (const part of linkPath.split("/")) {
    if (part === "" || part === ".") continue;
    if (part !== "..") {
      parts.push(part);
      continue;
    }
    if (parts.length === 0)
      return { problem: "evidence: relative link escapes repository " + target };
    parts.pop();
  }
  return { path: parts.join("/") };
}
export async function evidenceProblems(
  text: string,
  recordPath: string,
  isFile: (path: string) => boolean | Promise<boolean>,
): Promise<string[]> {
  const problems: string[] = [];
  const targets = [...text.matchAll(markdownLink), ...text.matchAll(referenceLink)];
  for (const match of targets) {
    const target = match[1] ?? match[2] ?? "";
    const resolved = resolveLink(target, recordPath);
    if (resolved.problem !== undefined) problems.push(resolved.problem);
    else if (resolved.path !== undefined && !(await isFile(resolved.path)))
      problems.push("evidence: relative link does not resolve to a file " + target);
  }
  return problems;
}
// Repository-root entries: infrastructure only; every record lives in the bundle.
const INFRA = new Set(["README.md", "mise.toml", ".gitignore", "dx.toml"]);
const INFRA_DIRS = new Set(["tools", BUNDLE]);

export function nameProblem(name: string, grammar: RegExp, expected: string): string | null {
  const m = grammar.exec(name);
  if (m === null) return `name must be ${expected}`;
  const [, y = "", mo = "", d = ""] = m;
  return validDay(y, mo, d) ? null : `name starts with an invalid date ${y}${mo}${d}`;
}

export function repoEntryProblem(name: string, isDirectory: boolean): string | null {
  if (name.startsWith(".")) return null;
  // Transitional: accept the old ticket home until the coordinator moves it to .agents/tickets/.
  if (isDirectory && name === "tickets") return null;
  const known = isDirectory ? INFRA_DIRS.has(name) : INFRA.has(name);
  return known
    ? null
    : `not repository infrastructure: records and their data belong in ${BUNDLE}/`;
}

export function bundleEntryProblem(name: string, isDirectory: boolean): string | null {
  if (isDirectory) return name === RAW ? null : `${BUNDLE}/ is flat: no subdirectory but raw/`;
  if (RESERVED.has(name)) return null;
  if (!name.endsWith(".md")) return "a non-Markdown file belongs in raw/";
  return nameProblem(name, CONCEPT_NAME, "{yyyymmdd}_{hyphen-connected-slug}.md");
}

export function rawEntryProblem(name: string, isDirectory: boolean): string | null {
  if (isDirectory) return "raw/ is flat";
  return nameProblem(name, RAW_NAME, "{yyyymmdd}_{slug}.{ext}, not .md");
}

export function supersessionProblems(fm: Frontmatter, known: ReadonlySet<string>): string[] {
  const next = fm.superseded_by;
  if (next === undefined) return [];
  const problems: string[] = [];
  if (fm.status !== "deprecated") problems.push("superseded_by requires status: deprecated");
  if (!known.has(next)) problems.push("superseded_by names a missing record " + next);
  return problems;
}

// Revision trees contain files; infer their parent directories for layout checks.
export function layoutFindings(files: readonly string[]): Finding[] {
  const entries = new Map<string, boolean>();
  for (const path of files) {
    const parts = path.split("/");
    for (let i = 1; i < parts.length; i += 1) entries.set(parts.slice(0, i).join("/"), true);
    entries.set(path, false);
  }
  const findings: Finding[] = [];
  for (const [path, directory] of entries) {
    const parts = path.split("/");
    let problem: string | null = null;
    if (parts.length === 1) problem = repoEntryProblem(path, directory);
    else if (parts[0] === BUNDLE && parts.length === 2)
      problem = bundleEntryProblem(parts[1] ?? "", directory);
    else if (parts[0] === BUNDLE && parts[1] === RAW && parts.length === 3)
      problem = rawEntryProblem(parts[2] ?? "", directory);
    if (problem !== null) findings.push({ path, problem });
  }
  return findings;
}
